// src/api/inventory.js
// FIX: Corrected import path to go up one level to src/ and then into api/
import apiClient from '../api/ api';

export const fetchInventoryItems = async () => {
  try {
    // Assuming admin/inventory is accessible, or adjust endpoint if inventory is public
    const response = await apiClient.get('/admin/inventory');
    return response.data.data;
  } catch (error) {
    console.error("Error fetching inventory:", error.response?.data?.message || error.message);
    throw error;
  }
};
